import numpy as np
import pandas as pd
import pytest

from elfantasy.model.prices import PriceModel
from elfantasy.rules import RULES_2026_27 as R

A, B, C = 0.04, -0.046, 0.04  # the shape fitted on 2026-27


def history(n: int = 400, seed: int = 0) -> pd.DataFrame:
    """Price changes generated by the known rule, including the floor and DNPs."""
    rng = np.random.default_rng(seed)
    price = np.round(rng.uniform(4.0, 18.0, n), 1)
    fp = rng.normal(1.1 * price, 6)
    played = rng.random(n) > 0.15
    is_coach = np.zeros(n, bool)
    is_coach[:40] = True
    raw = np.where(played | is_coach, A * fp + B * price + C, -0.1)
    nxt = np.maximum(R.min_price, np.round(price + np.round(raw / 0.1) * 0.1, 1))
    return pd.DataFrame({"round": rng.integers(1, 10, n), "player_id": range(n),
                         "is_coach": is_coach, "price": price, "next_price": nxt,
                         "fp": np.where(played | is_coach, fp, 0.0), "played": played})  # fmt: skip


def test_fit_recovers_the_rule():
    m = PriceModel.fit(history(), R)
    assert m.player_coef == pytest.approx([A, B, C], abs=0.004)
    assert m.dnp_change == pytest.approx(-0.1)


def test_change_reproduces_prices_and_respects_floor():
    h = history()
    m = PriceModel.fit(h, R)
    new = h["price"] + m.change(h["price"], h["fp"], h["played"], h["is_coach"])
    assert np.isclose(new, h["next_price"]).mean() > 0.9
    assert (new >= R.min_price - 1e-9).all()
    # A player at the floor who doesn't play stays at the floor.
    assert m.change([4.0], [0.0], [False], [False])[0] == pytest.approx(0.0)


def test_break_even_and_cheaper_players_rise_more():
    m = PriceModel.fit(history(), R)
    assert m.break_even(15.0) > m.break_even(8.0)
    # Same points, cheaper player: bigger rise.
    assert (
        m.change([6.0], [15.0], [True], [False])[0] > m.change([14.0], [15.0], [True], [False])[0]
    )


def test_expected_change_weights_the_chance_of_playing():
    m = PriceModel.fit(history(), R)
    sure = m.expected_change([10.0], [1.0], [20.0], [False])[0]
    doubtful = m.expected_change([10.0], [0.5], [20.0], [False])[0]
    out = m.expected_change([10.0], [0.0], [20.0], [False])[0]
    assert sure > doubtful > out
    assert out == pytest.approx(m.dnp_change)
    assert m.expected_change([4.0], [0.0], [0.0], [False])[0] == pytest.approx(0.0)  # floor


def test_rise_probability():
    m = PriceModel.fit(history(), R)
    pred = pd.DataFrame({"p_play": [1.0, 1.0, 0.5], "q10": [5.0, 15.0, 15.0],
                         "q50": [10.0, 22.0, 22.0], "q90": [15.0, 30.0, 30.0]})  # fmt: skip
    p = m.rise_probability(np.array([12.0, 12.0, 12.0]), pred)
    assert p[1] > 0.5 > p[0]  # break-even ~13.6: likely beaten by the second player
    assert p[2] == pytest.approx(p[1] / 2)


def test_too_little_history():
    assert PriceModel.fit(history(n=30), R) is None
